mapper.select:
SELECT pa.attempt_no AS requestNo, pa.payment_order_id AS paymentOrderId, pa.prepay_order_no AS prepayOrderNo, pr.pay_scene AS payScene, po.order_no AS orderNo, pa.payment_method AS paymentMethod, pa.channel_code AS channelCode, attempt_route.route_result AS routeResult, pa.terminal AS terminal, pa.client_ip AS clientIp, pa.idempotency_key AS idempotencyKey, pa.attempt_status AS requestStatus, pa.attempt_status_type AS requestStatusType, pa.request_payload AS requestPayload, pa.response_payload AS responsePayload, DATE_FORMAT(pa.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt,
FROM t_payment_attempt pa
LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(1) AS totalRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '成功' THEN 1 ELSE 0 END), 0) AS successRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '失败' THEN 1 ELSE 0 END), 0) AS failedRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status IN ('处理中', '待人工确认', '渠道提交中') THEN 1 ELSE 0 END), 0) AS processingRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '等待回调' THEN 1 ELSE 0 END), 0) AS waitingCallbackRequestCount, COUNT(DISTINCT NULLIF(filtered_requests.terminal, '')) AS distinctTerminalCount, COUNT(DISTINCT NULLIF(filtered_requests.channel_code, '')) AS distinctChannelCount, COALESCE(( SELECT COUNT(1) FROM ( SELECT repeated_requests.payment_order_id FROM ( SELECT pa.payment_order_id, pa.response_payload, pa.attempt_status, pa.terminal, pa.channel_code, pa.client_ip, po.order_no, pa.attempt_no FROM t_payment_attempt pa
) repeated_requests WHERE repeated_requests.payment_order_id IS NOT NULL GROUP BY repeated_requests.payment_order_id HAVING COUNT(1) > 1 ) repeated_payment_orders ), 0) AS repeatedPaymentOrderCount, COALESCE(SUM(CASE WHEN filtered_requests.response_payload IS NULL OR filtered_requests.response_payload = '' THEN 1 ELSE 0 END), 0) AS missingResponseCount, MAX(DATE_FORMAT(filtered_requests.created_at, '%Y-%m-%d %H:%i:%s')) AS latestRequestAt FROM ( SELECT pa.payment_order_id, pa.response_payload, pa.attempt_status, pa.terminal, pa.channel_code, pa.client_ip, pa.created_at, po.order_no, pa.attempt_no FROM t_payment_attempt pa
) filtered_requests
